//! Vector-driven conformance tests for `raven-tcpip-wire`.
//!
//! Every case in `spec/tcpip/vectors/headers.toml` is a named test generated by `build.rs`.
//! The small TOML reader below understands exactly the subset used by that file; the crate
//! itself remains dependency-free.

use std::sync::OnceLock;

use raven_tcpip_wire::ParseError;
use raven_tcpip_wire::arp::{ArpBuilder, ArpPacket};
use raven_tcpip_wire::checksum::{
    ChecksumContext, incremental_update, internet_checksum, pseudo_header_v4, pseudo_header_v6,
};
use raven_tcpip_wire::ethernet::{EtherType, EthernetBuilder, EthernetFrame, MacAddr};
use raven_tcpip_wire::icmpv4::{Icmpv4Builder, Icmpv4Packet};
use raven_tcpip_wire::icmpv6::{Icmpv6Builder, Icmpv6Packet};
use raven_tcpip_wire::ipv4::{Ipv4Addr, Ipv4Builder, Ipv4Flags, Ipv4Header, Ipv4Packet};
use raven_tcpip_wire::ipv6::{
    ExtensionKind, Ipv6Addr, Ipv6Builder, Ipv6Header, Ipv6Packet, write_extension, write_fragment,
};
use raven_tcpip_wire::tcp::{SackBlocks, TcpBuilder, TcpFlags, TcpHeader, TcpOption, TcpPacket};
use raven_tcpip_wire::udp::{UdpBuilder, UdpPacket};

const SPEC: &str = include_str!("../../../spec/tcpip/vectors/headers.toml");

include!(concat!(env!("OUT_DIR"), "/vector_cases.rs"));

// ---------------------------------------------------------------------------------------------
// Minimal TOML subset reader
// ---------------------------------------------------------------------------------------------

#[derive(Debug, Clone, PartialEq, Eq)]
enum Value {
    Int(i64),
    Str(String),
    Array(Vec<Value>),
    Table(Vec<(String, Value)>),
}

struct Parser<'a> {
    bytes: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(text: &'a str) -> Self {
        Self {
            bytes: text.as_bytes(),
            pos: 0,
        }
    }

    fn skip_ws(&mut self) {
        while matches!(self.bytes.get(self.pos), Some(b' ' | b'\t' | b'\r' | b'\n')) {
            self.pos += 1;
        }
    }

    fn peek(&self) -> Option<u8> {
        self.bytes.get(self.pos).copied()
    }

    fn bump(&mut self) -> Option<u8> {
        let byte = self.peek()?;
        self.pos += 1;
        Some(byte)
    }

    fn value(&mut self) -> Value {
        self.skip_ws();
        match self.peek() {
            Some(b'{') => self.table(),
            Some(b'[') => self.array(),
            Some(b'"') => Value::Str(self.string()),
            _ => Value::Int(self.integer()),
        }
    }

    fn string(&mut self) -> String {
        assert_eq!(self.bump(), Some(b'"'));
        let mut out = String::new();
        while let Some(byte) = self.bump() {
            if byte == b'"' {
                return out;
            }
            out.push(char::from(byte));
        }
        panic!("unterminated string");
    }

    fn bare_key(&mut self) -> String {
        self.skip_ws();
        let mut out = String::new();
        while let Some(byte) = self.peek() {
            if byte.is_ascii_alphanumeric() || byte == b'_' || byte == b'-' {
                out.push(char::from(byte));
                self.pos += 1;
            } else {
                break;
            }
        }
        assert!(!out.is_empty(), "empty bare key");
        out
    }

    fn table(&mut self) -> Value {
        assert_eq!(self.bump(), Some(b'{'));
        let mut entries = Vec::new();
        loop {
            self.skip_ws();
            if self.peek() == Some(b'}') {
                self.pos += 1;
                break;
            }
            let key = self.bare_key();
            self.skip_ws();
            assert_eq!(self.bump(), Some(b'='));
            let value = self.value();
            entries.push((key, value));
            self.skip_ws();
            match self.peek() {
                Some(b',') => self.pos += 1,
                Some(b'}') => {
                    self.pos += 1;
                    break;
                }
                _ => break,
            }
        }
        Value::Table(entries)
    }

    fn array(&mut self) -> Value {
        assert_eq!(self.bump(), Some(b'['));
        let mut entries = Vec::new();
        loop {
            self.skip_ws();
            if self.peek() == Some(b']') {
                self.pos += 1;
                break;
            }
            entries.push(self.value());
            self.skip_ws();
            match self.peek() {
                Some(b',') => self.pos += 1,
                Some(b']') => {
                    self.pos += 1;
                    break;
                }
                _ => break,
            }
        }
        Value::Array(entries)
    }

    fn integer(&mut self) -> i64 {
        self.skip_ws();
        let negative = if self.peek() == Some(b'-') {
            self.pos += 1;
            true
        } else {
            false
        };
        let mut value: i64 = 0;
        let mut digits = 0;
        while let Some(byte) = self.peek() {
            if byte.is_ascii_digit() {
                value = value * 10 + i64::from(byte - b'0');
                digits += 1;
                self.pos += 1;
            } else {
                break;
            }
        }
        assert!(digits > 0, "integer expected");
        if negative { -value } else { value }
    }
}

#[derive(Debug, Clone, Default)]
struct ContextSpec {
    family: String,
    src: String,
    dst: String,
}

#[derive(Debug, Clone, Default)]
struct Case {
    name: String,
    proto: String,
    bytes: Vec<u8>,
    context: Option<ContextSpec>,
    expect: Option<Value>,
    reject: Option<String>,
}

fn parse_cases(text: &str) -> Vec<Case> {
    let mut cases = Vec::new();
    let mut current: Option<Case> = None;
    for raw in text.lines() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        if line == "[[case]]" {
            if let Some(case) = current.take() {
                cases.push(case);
            }
            current = Some(Case::default());
            continue;
        }
        let Some(case) = current.as_mut() else {
            continue;
        };
        let Some((key, value)) = line.split_once('=') else {
            continue;
        };
        let mut parser = Parser::new(value.trim());
        let value = parser.value();
        match key.trim() {
            "name" => case.name = value_as_str(&value).to_string(),
            "proto" => case.proto = value_as_str(&value).to_string(),
            "bytes" => case.bytes = parse_hex(value_as_str(&value)),
            "context" => case.context = Some(parse_context(&value)),
            "expect" => case.expect = Some(value),
            "reject" => case.reject = Some(value_as_str(&value).to_string()),
            _ => {}
        }
    }
    if let Some(case) = current {
        cases.push(case);
    }
    cases
}

fn parse_context(value: &Value) -> ContextSpec {
    ContextSpec {
        family: str_field(value, "family").to_string(),
        src: str_field(value, "src").to_string(),
        dst: str_field(value, "dst").to_string(),
    }
}

fn parse_hex(text: &str) -> Vec<u8> {
    text.split_whitespace()
        .map(|octet| u8::from_str_radix(octet, 16).expect("hex octet"))
        .collect()
}

fn value_as_str(value: &Value) -> &str {
    match value {
        Value::Str(text) => text,
        _ => panic!("string expected, got {value:?}"),
    }
}

fn field<'a>(value: &'a Value, key: &str) -> Option<&'a Value> {
    match value {
        Value::Table(entries) => entries
            .iter()
            .find(|(name, _)| name == key)
            .map(|(_, value)| value),
        _ => None,
    }
}

fn expect_field<'a>(value: &'a Value, key: &str) -> &'a Value {
    field(value, key).unwrap_or_else(|| panic!("missing field `{key}` in {value:?}"))
}

fn int_field(value: &Value, key: &str) -> i64 {
    match expect_field(value, key) {
        Value::Int(number) => *number,
        other => panic!("`{key}` is not an integer: {other:?}"),
    }
}

fn str_field<'a>(value: &'a Value, key: &str) -> &'a str {
    match expect_field(value, key) {
        Value::Str(text) => text,
        other => panic!("`{key}` is not a string: {other:?}"),
    }
}

fn array_field<'a>(value: &'a Value, key: &str) -> &'a [Value] {
    match expect_field(value, key) {
        Value::Array(items) => items,
        other => panic!("`{key}` is not an array: {other:?}"),
    }
}

fn as_i64(value: usize) -> i64 {
    i64::try_from(value).expect("usize fits i64")
}

fn parse_ipv4(text: &str) -> Ipv4Addr {
    let mut octets = [0u8; 4];
    let mut count = 0;
    for part in text.split('.') {
        octets[count] = part.parse().expect("IPv4 octet");
        count += 1;
    }
    assert_eq!(count, 4, "IPv4 needs four octets: {text}");
    Ipv4Addr::new(octets)
}

fn parse_ipv6(text: &str) -> Ipv6Addr {
    let (head, tail) = match text.split_once("::") {
        Some((head, tail)) => (head, Some(tail)),
        None => (text, None),
    };
    let mut groups = Vec::new();
    for part in head.split(':') {
        if !part.is_empty() {
            groups.push(u16::from_str_radix(part, 16).expect("IPv6 group"));
        }
    }
    if let Some(tail) = tail {
        let mut trailing = Vec::new();
        for part in tail.split(':') {
            if !part.is_empty() {
                trailing.push(u16::from_str_radix(part, 16).expect("IPv6 group"));
            }
        }
        while groups.len() + trailing.len() < 8 {
            groups.push(0);
        }
        groups.extend(trailing);
    }
    assert_eq!(groups.len(), 8, "IPv6 needs eight groups: {text}");
    let mut octets = [0u8; 16];
    for (index, group) in groups.iter().enumerate() {
        let bytes = group.to_be_bytes();
        octets[index * 2] = bytes[0];
        octets[index * 2 + 1] = bytes[1];
    }
    Ipv6Addr::new(octets)
}

fn default_context() -> ChecksumContext {
    ChecksumContext::ipv4(parse_ipv4("192.0.2.1"), parse_ipv4("198.51.100.2"))
}

fn default_context_v6() -> ChecksumContext {
    ChecksumContext::ipv6(parse_ipv6("2001:db8::1"), parse_ipv6("2001:db8::2"))
}

fn context_for(case: &Case) -> ChecksumContext {
    match &case.context {
        Some(context) if context.family == "ipv6" => {
            ChecksumContext::ipv6(parse_ipv6(&context.src), parse_ipv6(&context.dst))
        }
        Some(_) => default_context(),
        // The ICMPv6 vectors use the same addresses as the IPv6 packet vectors. The sibling
        // `.md` says the context supplies them; the TOML omits the table, so this is the
        // documented default for that protocol.
        None if case.proto == "icmpv6" => default_context_v6(),
        None => default_context(),
    }
}

static CASES: OnceLock<Vec<Case>> = OnceLock::new();

fn cases() -> &'static [Case] {
    CASES.get_or_init(|| parse_cases(SPEC))
}

fn find_case(name: &str) -> &'static Case {
    cases()
        .iter()
        .find(|case| case.name == name)
        .unwrap_or_else(|| panic!("header vector `{name}` is missing from headers.toml"))
}

// ---------------------------------------------------------------------------------------------
// Case runner
// ---------------------------------------------------------------------------------------------

/// The TOML row for `tcp-bad-data-offset-high` carries 60 octets with a
/// well-formed 60-byte header and a valid checksum, while `headers.md` line 186
/// pins the intended case as “a data offset of 15 with only 20 bytes”. Use the
/// documented 20-byte form so the case exercises `tcp.data_offset`; the parser
/// itself must keep accepting legal 60-byte headers.
fn vector_bytes(case: &Case) -> &[u8] {
    if case.name == "tcp-bad-data-offset-high" && case.bytes.len() == 60 {
        &case.bytes[..20]
    } else {
        &case.bytes
    }
}

fn run_case(name: &str) {
    let case = find_case(name);
    let context = context_for(case);
    let bytes = vector_bytes(case);
    if let Some(expected_tag) = &case.reject {
        let outcome = parse_outcome(case, bytes, context);
        let error = match outcome {
            Ok(()) => panic!("case `{name}` parsed successfully, expected `{expected_tag}`"),
            Err(error) => error,
        };
        assert_eq!(
            error.tag(),
            expected_tag,
            "case `{name}` returned the wrong reason tag: {error:?}"
        );
        return;
    }

    let expect = case
        .expect
        .as_ref()
        .expect("valid case has an expect table");
    match case.proto.as_str() {
        "ipv4" => check_ipv4(&Ipv4Packet::parse(bytes).expect(name), expect),
        "ipv6" => check_ipv6(&Ipv6Packet::parse(bytes).expect(name), expect),
        "tcp" => check_tcp(&TcpPacket::parse(bytes, context).expect(name), expect),
        "udp" => check_udp(&UdpPacket::parse(bytes, context).expect(name), expect),
        "icmp" => check_icmpv4(&Icmpv4Packet::parse(bytes).expect(name), expect),
        "icmpv6" => check_icmpv6(&Icmpv6Packet::parse(bytes, context).expect(name), expect),
        "arp" => check_arp(&ArpPacket::parse(bytes).expect(name), expect),
        other => panic!("unknown proto `{other}` in case `{name}`"),
    }
}

#[test]
fn high_data_offset_vector_uses_the_documented_20_byte_form() {
    let case = find_case("tcp-bad-data-offset-high");
    let bytes = vector_bytes(case);
    assert_eq!(bytes.len(), 20);
    let error = parse_outcome(case, bytes, context_for(case))
        .expect_err("20 bytes with data offset 15 must reject");
    assert_eq!(error.tag(), "tcp.data_offset");
}

#[test]
fn a_legal_60_byte_tcp_header_is_accepted() {
    let bytes = parse_hex(
        "9c 40 00 50 00 00 00 01 00 00 00 00 f0 02 ff ff 86 f1 00 00 \
         00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 \
         00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00",
    );
    assert_eq!(bytes.len(), 60);
    let parsed = TcpPacket::parse(&bytes, default_context())
        .expect("a 60-byte header that fits and checksums is legal");
    assert_eq!(parsed.data_offset(), 15);
    assert_eq!(parsed.header_len(), 60);
    assert_eq!(parsed.payload_len(), 0);
}

fn parse_outcome(case: &Case, bytes: &[u8], context: ChecksumContext) -> Result<(), ParseError> {
    match case.proto.as_str() {
        "ipv4" => Ipv4Packet::parse(bytes).map(|_| ()),
        "ipv6" => Ipv6Packet::parse(bytes).map(|_| ()),
        "tcp" => TcpPacket::parse(bytes, context).map(|_| ()),
        "udp" => UdpPacket::parse(bytes, context).map(|_| ()),
        "icmp" => Icmpv4Packet::parse(bytes).map(|_| ()),
        "icmpv6" => Icmpv6Packet::parse(bytes, context).map(|_| ()),
        "arp" => ArpPacket::parse(bytes).map(|_| ()),
        other => panic!("unknown proto `{other}`"),
    }
}

fn check_ipv4(packet: &Ipv4Packet<'_>, expect: &Value) {
    assert_eq!(i64::from(packet.version()), int_field(expect, "version"));
    assert_eq!(i64::from(packet.ihl()), int_field(expect, "ihl"));
    assert_eq!(i64::from(packet.dscp()), int_field(expect, "dscp"));
    assert_eq!(i64::from(packet.ecn()), int_field(expect, "ecn"));
    assert_eq!(
        i64::from(packet.total_len()),
        int_field(expect, "total_len")
    );
    assert_eq!(i64::from(packet.id()), int_field(expect, "id"));
    assert_eq!(packet.flags().to_string(), str_field(expect, "flags"));
    assert_eq!(
        i64::from(packet.frag_offset()),
        int_field(expect, "frag_offset")
    );
    assert_eq!(i64::from(packet.ttl()), int_field(expect, "ttl"));
    assert_eq!(i64::from(packet.protocol()), int_field(expect, "protocol"));
    assert_eq!(i64::from(packet.checksum()), int_field(expect, "checksum"));
    assert_eq!(packet.src().to_string(), str_field(expect, "src"));
    assert_eq!(packet.dst().to_string(), str_field(expect, "dst"));
    assert_eq!(
        as_i64(packet.payload_len()),
        int_field(expect, "payload_len")
    );
}

fn check_ipv6(packet: &Ipv6Packet<'_>, expect: &Value) {
    assert_eq!(i64::from(packet.version()), int_field(expect, "version"));
    assert_eq!(
        i64::from(packet.traffic_class()),
        int_field(expect, "traffic_class")
    );
    assert_eq!(
        i64::from(packet.flow_label()),
        int_field(expect, "flow_label")
    );
    assert_eq!(
        i64::from(packet.payload_len()),
        int_field(expect, "payload_len")
    );
    assert_eq!(
        i64::from(packet.next_header()),
        int_field(expect, "next_header")
    );
    assert_eq!(
        i64::from(packet.hop_limit()),
        int_field(expect, "hop_limit")
    );
    assert_eq!(packet.src().to_string(), str_field(expect, "src"));
    assert_eq!(packet.dst().to_string(), str_field(expect, "dst"));
}

fn check_tcp(packet: &TcpPacket<'_>, expect: &Value) {
    assert_eq!(i64::from(packet.src_port()), int_field(expect, "src_port"));
    assert_eq!(i64::from(packet.dst_port()), int_field(expect, "dst_port"));
    assert_eq!(i64::from(packet.sequence()), int_field(expect, "seq"));
    assert_eq!(
        i64::from(packet.acknowledgement()),
        int_field(expect, "ack")
    );
    assert_eq!(
        i64::from(packet.data_offset()),
        int_field(expect, "data_offset")
    );
    assert_eq!(packet.flags().to_string(), str_field(expect, "flags"));
    assert_eq!(i64::from(packet.window()), int_field(expect, "window"));
    assert_eq!(i64::from(packet.checksum()), int_field(expect, "checksum"));
    assert_eq!(
        i64::from(packet.urgent_pointer()),
        int_field(expect, "urgent")
    );
    assert_eq!(
        as_i64(packet.payload_len()),
        int_field(expect, "payload_len")
    );
    check_tcp_options(packet, expect);
}

fn option_kind(option: &TcpOption<'_>) -> u8 {
    match option {
        TcpOption::EndOfList => 0,
        TcpOption::NoOperation => 1,
        TcpOption::MaxSegmentSize(_) => 2,
        TcpOption::WindowScale(_) => 3,
        TcpOption::SackPermitted => 4,
        TcpOption::Sack(_) => 5,
        TcpOption::Timestamps { .. } => 8,
        TcpOption::Md5 { .. } => 19,
        TcpOption::Authentication { .. } => 29,
        TcpOption::Unknown { kind, .. } => *kind,
    }
}

fn check_tcp_options(packet: &TcpPacket<'_>, expect: &Value) {
    let expected = array_field(expect, "options");
    let actual: Vec<TcpOption<'_>> = packet
        .options()
        .map(|option| option.expect("option parses"))
        .collect();
    assert_eq!(actual.len(), expected.len(), "option count");
    for (index, (option, expected)) in actual.iter().zip(expected).enumerate() {
        assert_eq!(
            i64::from(option_kind(option)),
            int_field(expected, "kind"),
            "option {index} kind"
        );
        match str_field(expected, "name") {
            "eol" => assert!(matches!(option, TcpOption::EndOfList)),
            "nop" => assert!(matches!(option, TcpOption::NoOperation)),
            "mss" => match option {
                TcpOption::MaxSegmentSize(mss) => {
                    assert_eq!(i64::from(*mss), int_field(expected, "mss"));
                }
                other => panic!("option {index}: expected MSS, got {other:?}"),
            },
            "window_scale" => match option {
                TcpOption::WindowScale(shift) => {
                    assert_eq!(i64::from(*shift), int_field(expected, "shift"));
                }
                other => panic!("option {index}: expected window scale, got {other:?}"),
            },
            "sack_permitted" => assert!(matches!(option, TcpOption::SackPermitted)),
            "sack" => match option {
                TcpOption::Sack(blocks) => check_sack_blocks(*blocks, expected),
                other => panic!("option {index}: expected SACK, got {other:?}"),
            },
            "timestamps" => match option {
                TcpOption::Timestamps { tsval, tsecr } => {
                    assert_eq!(i64::from(*tsval), int_field(expected, "tsval"));
                    assert_eq!(i64::from(*tsecr), int_field(expected, "tsecr"));
                }
                other => panic!("option {index}: expected timestamps, got {other:?}"),
            },
            "unknown" => match option {
                TcpOption::Unknown { kind, data } => {
                    assert_eq!(i64::from(*kind), int_field(expected, "kind"));
                    assert_eq!(as_i64(2 + data.len()), int_field(expected, "length"));
                }
                other => panic!("option {index}: expected unknown, got {other:?}"),
            },
            other => panic!("option {index}: unknown expectation `{other}`"),
        }
    }
}

fn check_sack_blocks(blocks: SackBlocks<'_>, expected: &Value) {
    let expected_blocks = array_field(expected, "blocks");
    let actual: Vec<(u32, u32)> = blocks.collect();
    assert_eq!(actual.len(), expected_blocks.len(), "SACK block count");
    for (block, expected_block) in actual.iter().zip(expected_blocks) {
        let pair = match expected_block {
            Value::Array(pair) => pair,
            other => panic!("SACK block is not an array: {other:?}"),
        };
        assert_eq!(pair.len(), 2, "SACK block needs left and right");
        let left = match &pair[0] {
            Value::Int(value) => *value,
            other => panic!("SACK left is not an integer: {other:?}"),
        };
        let right = match &pair[1] {
            Value::Int(value) => *value,
            other => panic!("SACK right is not an integer: {other:?}"),
        };
        assert_eq!(i64::from(block.0), left);
        assert_eq!(i64::from(block.1), right);
    }
}

fn check_udp(packet: &UdpPacket<'_>, expect: &Value) {
    assert_eq!(i64::from(packet.src_port()), int_field(expect, "src_port"));
    assert_eq!(i64::from(packet.dst_port()), int_field(expect, "dst_port"));
    assert_eq!(i64::from(packet.length()), int_field(expect, "length"));
    assert_eq!(i64::from(packet.checksum()), int_field(expect, "checksum"));
    assert_eq!(
        as_i64(packet.payload_len()),
        int_field(expect, "payload_len")
    );
}

fn check_icmpv4(packet: &Icmpv4Packet<'_>, expect: &Value) {
    assert_eq!(i64::from(packet.message_type()), int_field(expect, "type"));
    assert_eq!(i64::from(packet.code()), int_field(expect, "code"));
    assert_eq!(i64::from(packet.checksum()), int_field(expect, "checksum"));
    assert_eq!(i64::from(packet.rest()), int_field(expect, "rest"));
    if field(expect, "id").is_some() {
        assert_eq!(i64::from(packet.id()), int_field(expect, "id"));
    }
    if field(expect, "seq").is_some() {
        assert_eq!(i64::from(packet.sequence()), int_field(expect, "seq"));
    }
    if field(expect, "mtu").is_some() {
        let expected = int_field(expect, "mtu");
        assert_eq!(packet.mtu().map(i64::from), Some(expected), "ICMPv4 MTU");
    }
    assert_eq!(
        as_i64(packet.payload_len()),
        int_field(expect, "payload_len")
    );
}

fn check_icmpv6(packet: &Icmpv6Packet<'_>, expect: &Value) {
    assert_eq!(i64::from(packet.message_type()), int_field(expect, "type"));
    assert_eq!(i64::from(packet.code()), int_field(expect, "code"));
    assert_eq!(i64::from(packet.checksum()), int_field(expect, "checksum"));
    assert_eq!(i64::from(packet.rest()), int_field(expect, "rest"));
    if field(expect, "id").is_some() {
        assert_eq!(i64::from(packet.id()), int_field(expect, "id"));
    }
    if field(expect, "seq").is_some() {
        assert_eq!(i64::from(packet.sequence()), int_field(expect, "seq"));
    }
    if field(expect, "mtu").is_some() {
        assert_eq!(
            packet.mtu().map(i64::from),
            Some(int_field(expect, "mtu")),
            "ICMPv6 MTU"
        );
    }
    if field(expect, "target").is_some() {
        assert_eq!(
            packet.target().map(|target| target.to_string()),
            Some(str_field(expect, "target").to_string()),
            "ICMPv6 target"
        );
    }
    assert_eq!(
        as_i64(packet.payload_len()),
        int_field(expect, "payload_len")
    );
}

fn check_arp(packet: &ArpPacket<'_>, expect: &Value) {
    assert_eq!(
        i64::from(packet.hardware_type()),
        int_field(expect, "htype")
    );
    assert_eq!(
        i64::from(packet.protocol_type()),
        int_field(expect, "ptype")
    );
    assert_eq!(i64::from(packet.hardware_len()), int_field(expect, "hlen"));
    assert_eq!(i64::from(packet.protocol_len()), int_field(expect, "plen"));
    assert_eq!(i64::from(packet.operation()), int_field(expect, "oper"));
    assert_eq!(
        packet.sender_hardware().to_string(),
        str_field(expect, "sha")
    );
    assert_eq!(
        packet.sender_protocol().to_string(),
        str_field(expect, "spa")
    );
    assert_eq!(
        packet.target_hardware().to_string(),
        str_field(expect, "tha")
    );
    assert_eq!(
        packet.target_protocol().to_string(),
        str_field(expect, "tpa")
    );
}

