#[test]
fn vector_inventory_matches_the_pinned_contract() {
    let names: Vec<&str> = cases().iter().map(|case| case.name.as_str()).collect();
    assert_eq!(
        names.as_slice(),
        GENERATED_CASE_NAMES,
        "headers.toml must contain exactly the pinned cases, in order"
    );
}

#[test]
fn vector_inventory_protocol_counts() {
    let mut ipv4 = 0;
    let mut ipv6 = 0;
    let mut tcp = 0;
    let mut udp = 0;
    let mut icmp = 0;
    let mut icmpv6 = 0;
    let mut arp = 0;
    let mut valid = 0;
    let mut rejected = 0;
    for case in cases() {
        match case.proto.as_str() {
            "ipv4" => ipv4 += 1,
            "ipv6" => ipv6 += 1,
            "tcp" => tcp += 1,
            "udp" => udp += 1,
            "icmp" => icmp += 1,
            "icmpv6" => icmpv6 += 1,
            "arp" => arp += 1,
            other => panic!("unknown proto `{other}`"),
        }
        if case.reject.is_some() {
            rejected += 1;
        } else {
            valid += 1;
        }
    }
    assert_eq!(
        (ipv4, ipv6, tcp, udp, icmp, icmpv6, arp),
        (16, 13, 19, 8, 8, 9, 8)
    );
    assert_eq!((valid, rejected), (50, 31));
}

#[test]
fn every_valid_packet_prefix_shorter_than_its_fixed_header_is_truncated() {
    for case in cases() {
        if case.reject.is_some() {
            continue;
        }
        let minimum = match case.proto.as_str() {
            "ipv4" | "tcp" => 20,
            "ipv6" => 40,
            "udp" | "icmp" | "icmpv6" => 8,
            "arp" => 28,
            other => panic!("unknown proto `{other}`"),
        };
        let context = context_for(case);
        for prefix in 0..minimum {
            let outcome = parse_outcome(case, &case.bytes[..prefix], context);
            match outcome {
                Ok(()) => panic!("case `{}`: prefix {prefix} parsed successfully", case.name),
                Err(error) => assert!(
                    error.tag().ends_with(".truncated"),
                    "case `{}`: prefix {prefix} gave `{}`",
                    case.name,
                    error.tag()
                ),
            }
        }
    }
}

