#[test]
fn incremental_update_matches_full_recomputation_over_1000_mutations() {
    let mut buffer = [0u8; 64];
    for (index, slot) in buffer.iter_mut().enumerate() {
        *slot = (index as u8).wrapping_mul(37).wrapping_add(11);
    }
    let mut current_checksum = internet_checksum(&[&buffer]);
    let mut state: u64 = 0x9e37_79b9_7f4a_7c15;
    for round in 0..1000 {
        state ^= state << 13;
        state ^= state >> 7;
        state ^= state << 17;
        let offset = usize::try_from(state % 32).expect("offset") * 2;
        let old_word = u16::from_be_bytes([buffer[offset], buffer[offset + 1]]);
        state ^= state << 13;
        state ^= state >> 7;
        state ^= state << 17;
        let new_word = u16::try_from(state & 0xffff).expect("word");
        buffer[offset..offset + 2].copy_from_slice(&new_word.to_be_bytes());
        let incremental = incremental_update(current_checksum, old_word, new_word);
        let full = internet_checksum(&[&buffer]);
        assert_eq!(
            incremental, full,
            "round {round}: incremental update disagrees with full recomputation"
        );
        current_checksum = full;
    }
}

