#[test]
fn md5_and_authentication_options_are_parsed() {
    let mut md5 = [0u8; 18];
    md5[0] = 0x13;
    md5[1] = 18;
    for (index, byte) in md5[2..].iter_mut().enumerate() {
        *byte = u8::try_from(index).expect("digest byte");
    }
    let mut options = raven_tcpip_wire::tcp::TcpOptions::new(&md5);
    match options.next().expect("MD5 option").expect("MD5 parses") {
        TcpOption::Md5 { digest } => assert_eq!(digest.len(), 16),
        other => panic!("expected MD5, got {other:?}"),
    }

    let ao = [0x1d, 8, 1, 2, 0xaa, 0xbb, 0xcc, 0xdd];
    let mut options = raven_tcpip_wire::tcp::TcpOptions::new(&ao);
    match options.next().expect("AO option").expect("AO parses") {
        TcpOption::Authentication { data } => {
            assert_eq!(data, [1, 2, 0xaa, 0xbb, 0xcc, 0xdd]);
        }
        other => panic!("expected AO, got {other:?}"),
    }
}

