#[test]
fn ipv6_hop_by_hop_chain_roundtrip() {
    let header = Ipv6Header {
        next_header: 0,
        src: parse_ipv6("2001:db8::1"),
        dst: parse_ipv6("2001:db8::2"),
        ..Ipv6Header::default()
    };
    let mut buffer = [0u8; 56];
    let packet = {
        let mut builder = Ipv6Builder::new(&mut buffer, &header, 16).expect("build IPv6");
        let payload = builder.payload_mut();
        let length = write_extension(&mut payload[..8], ExtensionKind::HopByHop, 6, 6)
            .expect("write hop-by-hop");
        assert_eq!(length, 8);
        payload[8..].copy_from_slice(b"tcp-data");
        builder.finish()
    };
    let parsed = Ipv6Packet::parse(packet).expect("parse IPv6");
    let extensions: Vec<_> = parsed.extensions().collect();
    assert_eq!(extensions.len(), 1);
    assert_eq!(extensions[0].kind, ExtensionKind::HopByHop);
    assert_eq!(extensions[0].next_header, 6);
    let (next, upper) = parsed.upper_layer();
    assert_eq!(next, 6);
    assert_eq!(upper, b"tcp-data");
}

